def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # The most common value is the background; aligned non-background
    # markers are joined by color 3.
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] != background]
        if len(cols) >= 2:
            for c in range(min(cols) + 1, max(cols)):
                if grid[r][c] == background:
                    out[r][c] = 3

    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != background]
        if len(rows) >= 2:
            for r in range(min(rows) + 1, max(rows)):
                if grid[r][c] == background:
                    out[r][c] = 3

    return out
